"use client";

import { useState } from "react";
import { motion, useReducedMotion } from "framer-motion";
import { ArrowRight } from "@phosphor-icons/react";
import ConfiguratorModal from "@/components/services/ConfiguratorModal";
import TransitionLink from "@/components/common/TransitionLink";
import {
  PRODUCTS,
  PROCESS_STEPS,
  CONDITIONS,
  PRODUCT_CALL_URL,
  type Product,
  type ProductId,
} from "@/lib/pricing";

const SECTION_PX = "px-6 md:px-12 lg:px-16 xl:px-24";

const formatPrice = (n: number) =>
  `${n.toLocaleString("ca-ES", { maximumFractionDigits: 0 })} €`;

function Reveal({ children, className }: { children: React.ReactNode; className?: string }) {
  const reduce = useReducedMotion();
  return (
    <motion.div
      className={className}
      initial={reduce ? false : { opacity: 0, y: 24 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-80px" }}
      transition={{ duration: 0.5, ease: "easeOut" }}
    >
      {children}
    </motion.div>
  );
}

function SectionHeader({ caption, title }: { caption: string; title: string }) {
  return (
    <div className="flex flex-col gap-4">
      <span className="text-caption uppercase text-text-secondary">{caption}</span>
      <h2 className="text-heading-h1 text-text-main">{title}</h2>
    </div>
  );
}

// ————————————————————————————————— Tríada de productes

function ProductCard({ product }: { product: Product }) {
  return (
    <TransitionLink
      href={`/serveis/${product.id}`}
      className="group flex flex-col gap-5 rounded-card border border-surface-border bg-surface-card p-8 transition-colors hover:border-surface-border-strong lg:p-10"
    >
      <h3 className="text-heading-h3 text-text-main">{product.name}</h3>
      <div className="flex flex-col gap-1.5">
        <span className="text-caption uppercase text-text-secondary">{product.priceLabel}</span>
        <span className="text-display-h5 text-text-main">{formatPrice(product.price)}</span>
        {product.configNote && (
          <span className="text-caption uppercase text-text-secondary">{product.configNote}</span>
        )}
      </div>
      <p className="text-body-sm text-text-secondary">{product.description}</p>
      <div className="mt-auto pt-2">
        <span className="inline-flex min-h-11 items-center gap-2 text-button-lg text-text-main underline underline-offset-8 decoration-1 group-hover:decoration-2">
          {product.cta}
          <ArrowRight size={16} weight="regular" className="transition-transform group-hover:translate-x-1" aria-hidden />
        </span>
      </div>
    </TransitionLink>
  );
}

function TriadaSection() {
  return (
    <section id="productes" className={`${SECTION_PX} pt-20 pb-10 bg-surface-base`}>
      <Reveal>
        <SectionHeader caption="TRES PRODUCTES, UNA LÒGICA" title="Punts de partida" />
      </Reveal>
      <Reveal className="mt-14">
        <div className="grid grid-cols-1 gap-6 md:grid-cols-3 3xl:grid-cols-4">
          {PRODUCTS.map((p) => (
            <ProductCard key={p.id} product={p} />
          ))}
          {/* A mida: banda full-width (3+1) a laptops; 4a cel·la (dashed, sense preu) a monitors ≥1920px */}
          <div className="flex flex-col gap-4 rounded-card border border-dashed border-surface-border-strong p-8 md:col-span-full md:flex-row md:items-center md:gap-8 lg:p-10 3xl:col-span-1 3xl:flex-col 3xl:items-start 3xl:gap-5">
            <div className="flex flex-1 flex-col gap-2">
              <span className="text-caption uppercase text-text-secondary">APPS, BRANDING I MÉS</span>
              <h3 className="text-heading-h3 text-text-main">Una altra cosa al cap?</h3>
              <p className="text-body-sm text-text-secondary">
                El que no encaixa al configurador el pressupostem junts després d’una trucada.
              </p>
            </div>
            <a
              href={PRODUCT_CALL_URL}
              target="_blank"
              rel="noopener noreferrer"
              className="group inline-flex min-h-11 shrink-0 items-center gap-2 text-button-lg text-text-main underline underline-offset-8 decoration-1 hover:decoration-2"
            >
              Reserva una trucada
              <ArrowRight size={16} className="transition-transform group-hover:translate-x-1" aria-hidden />
              <span className="sr-only">(s’obre en una pestanya nova)</span>
            </a>
          </div>
        </div>
      </Reveal>
    </section>
  );
}

// ————————————————————————————————— Procés + condicions

function ProcessSection() {
  return (
    <section className={`${SECTION_PX} py-20 bg-surface-base border-t border-surface-border`}>
      <Reveal>
        <SectionHeader caption="EL PROCÉS" title="Com treballem" />
      </Reveal>
      <Reveal className="mt-14">
        <div className="grid grid-cols-1 gap-8 sm:grid-cols-2 lg:grid-cols-4">
          {PROCESS_STEPS.map((step) => (
            <div key={step.num} className="flex flex-col gap-3 border-t border-surface-border pt-6">
              <span className="text-caption text-text-secondary">{step.num}</span>
              <h3 className="text-heading-h3 text-text-main">{step.title}</h3>
              <p className="text-body-sm text-text-secondary">{step.text}</p>
            </div>
          ))}
        </div>
        <ul className="mt-12 flex flex-wrap gap-x-8 gap-y-3">
          {CONDITIONS.map((c) => (
            <li key={c} className="text-caption uppercase text-text-secondary">
              {c}
            </li>
          ))}
        </ul>
      </Reveal>
    </section>
  );
}

// ————————————————————————————————— CTA final

function FinalCtaSection({ onConfigure }: { onConfigure: (id: ProductId) => void }) {
  return (
    <section className={`${SECTION_PX} py-24 bg-surface-base border-t border-surface-border`}>
      <Reveal>
        <h2 className="max-w-3xl text-display-h2 text-text-main">
          No saps per on començar? Configura la teva web en dos minuts.
        </h2>
        <div className="mt-10 flex flex-col gap-4">
          <button
            type="button"
            onClick={() => onConfigure("web")}
            className="group inline-flex min-h-11 items-center gap-2 self-start text-heading-h3 text-text-main underline underline-offset-8 decoration-1 hover:decoration-2"
          >
            Obre el configurador
            <ArrowRight size={22} className="transition-transform group-hover:translate-x-1" aria-hidden />
          </button>
          <p className="text-body-sm text-text-secondary">
            O si ho prefereixes,{" "}
            <a
              href={PRODUCT_CALL_URL}
              target="_blank"
              rel="noopener noreferrer"
              className="underline underline-offset-4 hover:text-text-main"
            >
              reserva 15 minuts
              <span className="sr-only"> (s’obre en una pestanya nova)</span>
            </a>{" "}
            i en parlem — sense compromís.
          </p>
        </div>
      </Reveal>
    </section>
  );
}

export default function ProductsView() {
  // Configurador full-screen (cortina). Mantenim el producte seleccionat
  // en tancar perquè l'animació de sortida no es talli.
  const [configProduct, setConfigProduct] = useState<ProductId | null>(null);
  const [configOpen, setConfigOpen] = useState(false);
  const openConfigurator = (id: ProductId) => {
    setConfigProduct(id);
    setConfigOpen(true);
  };

  return (
    <>
      <TriadaSection />
      <ProcessSection />
      <FinalCtaSection onConfigure={openConfigurator} />

      <ConfiguratorModal
        isOpen={configOpen}
        onClose={() => setConfigOpen(false)}
        productId={configProduct}
      />
    </>
  );
}
